async function joinRtc(rtc, liveId) {
  joining = true; showError("");
  try {
    if (rtc.provider && rtc.provider !== "artc") throw new Error(`舞台页目前只接了阿里云 RTC（artc），本场是 ${rtc.provider}`);
    if (!window.AliRtcEngine) throw new Error("阿里云 RTC 脚本没加载出来，刷新一下这个页面");
    const support = await withTimeout(window.AliRtcEngine.isSupported(), 10000, "浏览器 WebRTC 检测");
    if (!support.support) throw new Error(`当前浏览器不支持 AliRTC：${support.reason || "unknown"}`);
    window.AliRtcEngine.setLogLevel(3);
    engine = window.AliRtcEngine.getInstance();
    engine.on("videoSubscribeStateChanged", (userId, _old, next) => { if (next === 3) attachVideo(userId); else if (next === 1) detachVideo(userId); });
    engine.on("remoteUserOffLineNotify", (userId) => detachVideo(userId));
    engine.on("bye", (code) => { report("left", `bye ${code}`); });
    engine.on("authInfoWillExpire", () => report("warn", "RTC 鉴权快过期了，需要重新开播"));
    for (const name of ["bye", "remoteUserOnLineNotify", "remoteUserOffLineNotify", "videoSubscribeStateChanged", "audioSubscribeStateChanged", "connectionStatusChange", "networkQualityChanged"]) {
      if (name === "networkQualityChanged") continue;
      engine.on(name, (...args) => report("rtc", `${name} ${JSON.stringify(args).slice(0, 200)}`));
    }
    // A broadcast stage only watches: it publishes no mic or camera, so room noise never reaches the avatar.
    await call("setChannelProfile", "communication");
    await call("setDefaultPublishLocalAudioStream", false);
    await call("setDefaultPublishLocalVideoStream", false);
    await call("setDefaultSubscribeAllRemoteAudioStreams", true);
    await call("setDefaultSubscribeAllRemoteVideoStreams", true);
    await withTimeout(engine.joinChannel(rtc.token, rtc.user_id), 20000, "加入 RTC 频道");
    joinedLive = liveId;
    report("joined", rtc.channel_id || "");
